"""Entire Graph + Checkpoint integration used by the Buildathon product.

There is deliberately no synthetic graph/checkpoint provider in the product
path. If Entire is not installed or activated, the analysis fails clearly.
"""
from __future__ import annotations
import json, os, re, subprocess
from typing import Any


def _run(repo: str, args: list[str], timeout: int = 120) -> str:
    p=subprocess.run(["entire", *args], cwd=repo, capture_output=True, text=True, timeout=timeout)
    if p.returncode:
        raise RuntimeError((p.stderr or p.stdout or "entire command failed").strip())
    return p.stdout


def verify(repo: str) -> dict[str, Any]:
    version=_run(repo,["graph","version"]).strip()
    capabilities=None
    try: capabilities=_extract_json(_run(repo,["graph","capabilities","--json"]))
    except Exception: pass
    return {"available":True,"version":version,"capabilities":capabilities}


def _extract_json(text: str) -> Any:
    text=text.strip()
    try: return json.loads(text)
    except json.JSONDecodeError: pass
    starts=[i for i in (text.find("{"),text.find("[")) if i>=0]
    if not starts: return None
    start=min(starts)
    for end in range(len(text),start,-1):
        try: return json.loads(text[start:end])
        except json.JSONDecodeError: continue
    return None


def graph_snapshot(repo: str) -> dict[str, Any]:
    raw=_run(repo,["graph","snapshot","--repo","."])
    rows=[]
    for line in raw.splitlines():
        obj=_extract_json(line)
        if isinstance(obj,dict): rows.append(obj)
    return {"raw":raw,"rows":rows}


def _location(obj: dict[str, Any]):
    file=obj.get("file") or obj.get("path") or obj.get("file_path")
    line=obj.get("line") or obj.get("start_line")
    loc=obj.get("location")
    if isinstance(loc,dict):
        file=file or loc.get("file") or loc.get("path")
        line=line or loc.get("line") or loc.get("start_line")
    return (str(file) if file else None, int(line) if str(line).isdigit() else None)


def snapshot_entities(repo: str) -> list[dict[str, Any]]:
    rows=graph_snapshot(repo)["rows"]
    out=[]
    for row in rows:
        eid=row.get("entity_id") or row.get("id") or row.get("qualified_name") or row.get("name")
        file,line=_location(row)
        if eid and file:
            out.append({"entity_id":str(eid),"kind":str(row.get("kind") or row.get("type") or "symbol"),"file":file,"line":line or 0,"end_line":row.get("end_line") or row.get("endLine") or line or 0,"module":row.get("module") or "","signature":row.get("signature") or "","raw":row})
    return out


def search(repo: str, query: str, limit: int = 10) -> list[dict[str, Any]]:
    raw=_run(repo,["graph","search","--repo",".","--profile","full","--query",query])
    data=_extract_json(raw)
    if isinstance(data,dict):
        data=data.get("results") or data.get("hits") or data.get("data") or []
    if not isinstance(data,list): return []
    return [x for x in data[:limit] if isinstance(x,dict)]


def impact(repo: str, symbol: str) -> dict[str, Any]:
    short_sym = symbol.split(":")[-1] if ":" in symbol else symbol
    callers: list[dict[str, Any]] = []
    callees: list[dict[str, Any]] = []
    raw = ""
    try:
        raw = _run(repo, ["graph", "impact", "--repo", ".", "--symbol", short_sym])
        section = None
        for line in raw.splitlines():
            low = line.strip().lower()
            if low.startswith("callers"): section = "callers"; continue
            if low.startswith("callees"): section = "callees"; continue
            if any(low.startswith(k) for k in ("type consumers", "data flows", "co-change", "same-container")): section = None; continue
            if line.strip().startswith("-") and section and not line.strip().startswith("- none"):
                parts = line.strip()[1:].strip().split()
                if parts:
                    sym_name = parts[0]
                    file_match = re.search(r"\(([^,:]+)(?::(\d+))?", line)
                    f_name = file_match.group(1) if file_match else ""
                    l_num = int(file_match.group(2)) if (file_match and file_match.group(2)) else 0
                    item = {"entity_id": sym_name, "file": f_name, "line": l_num, "depth": 1}
                    (callers if section == "callers" else callees).append(item)
    except Exception:
        raw = ""

    # Enrich from snapshot relation records
    try:
        snap = graph_snapshot(repo)
        for row in snap.get("rows", []):
            if row.get("record_type") == "relation" and row.get("type") in ("CALLS", "CONSTRUCTS", "DATA_FLOWS"):
                to_id = str(row.get("to_id", ""))
                from_id = str(row.get("from_id", ""))
                if short_sym in to_id or symbol in to_id:
                    from_short = from_id.split(":")[-1] if ":" in from_id else from_id
                    if not any(c["entity_id"] == from_short for c in callers):
                        callers.append({"entity_id": from_short, "file": "", "line": 0, "depth": 1})
                elif short_sym in from_id or symbol in from_id:
                    to_short = to_id.split(":")[-1] if ":" in to_id else to_id
                    if not any(c["entity_id"] == to_short for c in callees):
                        callees.append({"entity_id": to_short, "file": "", "line": 0, "depth": 1})
    except Exception:
        pass

    return {"symbol": symbol, "callers": callers, "callees": callees, "raw": raw}


def checkpoint_for_commit(repo: str, commit: str) -> dict[str, Any]:
    try:
        raw=_run(repo,["explain","--commit",commit])
        data=_extract_json(raw)
        if isinstance(data,dict):
            data["raw"] = raw
            data.setdefault("commit_id", commit)
            data["evidence_source"] = "entire_cli"
            data["verification_state"] = "verified"
            return data
        return {
            "commit_id": commit,
            "raw": raw,
            "checkpoint_summary": raw[:2000],
            "agent_reasoning": raw,
            "prompt": "",
            "evidence_source": "entire_cli",
            "verification_state": "verified",
        }
    except Exception as exc:
        # Checkpoint content must come from `entire explain`; do not substitute
        # commit-message-derived simulation data when that command is unavailable.
        return {
            "commit_id": commit,
            "session_id": None,
            "prompt": "",
            "agent_reasoning": "",
            "checkpoint_summary": "Entire checkpoint evidence is unavailable.",
            "author": "",
            "timestamp": "",
            "raw": "",
            "evidence_source": "entire_cli",
            "verification_state": "partial",
            "unavailable_reason": str(exc),
        }


def semantic_diff(repo: str, base: str, head: str) -> dict[str, Any]:
    raw=_run(repo,["graph","diff","--repo",".",base,head])
    return {"base":base,"head":head,"raw":raw,"parsed":_extract_json(raw)}
from __future__ import annotations

import json
import subprocess
from pathlib import Path
from typing import Any

from integrations.entire import (
    checkpoint_for_commit,
    graph_snapshot,
    impact,
    snapshot_entities,
)


class PipelineError(RuntimeError):
    pass


def _git(repo: str, args: list[str], timeout: int = 30) -> str:
    p = subprocess.run(["git", "-C", repo, *args], capture_output=True, text=True, timeout=timeout)
    if p.returncode:
        raise PipelineError((p.stderr or p.stdout or "git command failed").strip())
    return p.stdout


def changed_files(repo: str, commit: str) -> list[str]:
    return [x for x in _git(repo, ["diff-tree", "--no-commit-id", "--name-only", "-r", commit]).splitlines() if x]


def changed_ranges(repo: str, commit: str) -> dict[str, list[tuple[int, int]]]:
    # Unified diff is only used to locate changed lines; semantic relationships
    # and impact come from Entire Graph.
    text = _git(repo, ["show", "--format=", "--unified=0", commit])
    result: dict[str, list[tuple[int, int]]] = {}
    current: str | None = None
    for line in text.splitlines():
        if line.startswith("+++ b/"):
            current = line[6:]
            continue
        if current and line.startswith("@@"):
            import re
            m = re.search(r"\+(\d+)(?:,(\d+))?", line)
            if m:
                start = int(m.group(1)); count = int(m.group(2) or "1")
                result.setdefault(current, []).append((start, start + max(count, 1) - 1))
    return result


def commit_meta(repo: str, commit: str) -> dict[str, str]:
    out = _git(repo, ["show", "-s", "--format=%H%n%an%n%aI%n%s", commit])
    parts = out.splitlines()
    return {"sha": parts[0] if parts else commit, "author": parts[1] if len(parts)>1 else "", "date": parts[2] if len(parts)>2 else "", "subject": parts[3] if len(parts)>3 else ""}


def _changed_entities(repo: str, commit: str) -> list[str]:
    entities = snapshot_entities(repo)
    ranges = changed_ranges(repo, commit)
    matches: list[tuple[int, str]] = []
    for e in entities:
        efile = e.get("file", "")
        eline = int(e.get("line") or 0)
        eend = int(e.get("end_line") or eline)
        if eline == 0 and eend == 0:
            continue
        for start, end in ranges.get(efile, []):
            if eline <= end and start <= eend:
                # Prefer the most specific entity by smallest span
                span = max(1, eend - eline)
                matches.append((span, e["entity_id"]))
                break
    if matches:
        return list(dict.fromkeys(x[1] for x in sorted(matches)))

    # If a semantic entity cannot be mapped to the hunk, query Entire Graph
    # using changed file names. This keeps the result evidence-backed rather
    # than inventing symbol names.
    result: list[str] = []
    for path in changed_files(repo, commit):
        try:
            from integrations.entire import search
            hits = search(repo, path, limit=5)
            for hit in hits:
                eid = hit.get("entity_id") or hit.get("symbol") or hit.get("name")
                if eid: result.append(str(eid))
        except Exception:
            continue
    return list(dict.fromkeys(result))


def recent_checkpoints(repo: str, head: str, limit: int = 12) -> list[dict[str, Any]]:
    commits = [x for x in _git(repo, ["log", f"-{max(1, min(limit, 30))}", "--format=%H"]).splitlines() if x]
    out=[]
    for sha in commits:
        if sha == head:
            continue
        try:
            out.append(checkpoint_for_commit(repo, sha))
        except Exception:
            continue
    return out


def build(repo: str, commit: str, repo_name: str | None = None) -> dict[str, Any]:
    files = changed_files(repo, commit)
    meta = commit_meta(repo, commit)
    entities = _changed_entities(repo, commit)
    if not entities and files:
        # File-level evidence is explicit, not a fabricated symbol.
        entities = [f"file:{f}" for f in files]

    graph_evidence: list[dict[str, Any]] = []
    all_affected: dict[str, dict[str, Any]] = {}
    queue: list[tuple[str, int]] = [(e, 1) for e in entities]
    visited = set(entities)

    while queue:
        curr_entity, depth = queue.pop(0)
        evidence = impact(repo, curr_entity)
        graph_evidence.append(evidence)
        for item in evidence.get("callers", []):
            eid = item.get("entity_id")
            if not eid:
                continue
            candidate = {"depth": depth, "changed_entity": curr_entity, "source": "entire_graph", "relationship": "callers", "file": item.get("file"), "line": item.get("line")}
            if eid not in all_affected or depth < all_affected[eid].get("depth", 999):
                all_affected[eid] = candidate
            if eid not in visited and depth < 3:
                visited.add(eid)
                queue.append((eid, depth + 1))

    checkpoint=checkpoint_for_commit(repo, commit)
    historical=recent_checkpoints(repo, commit)
    snapshot=graph_snapshot(repo)
    return {
        "repo": repo_name or Path(repo).name,
        "repo_path": str(Path(repo).resolve()),
        "commit": commit,
        "commit_meta": meta,
        "changed_files": files,
        "changed_entities": entities,
        "all_affected": all_affected,
        "graph_evidence": graph_evidence,
        "graph_snapshot": snapshot,
        "checkpoint": checkpoint,
        "historical_checkpoints": historical,
    }
from __future__ import annotations
import logging
import os
import uuid
from pathlib import Path

from engine.entire_pipeline import build, PipelineError
from engine.test_inventory import inventory, rank
from risk_engine.scorer import score_change
from llm_agent.agent import analyze as llm_analyze
from integrations.databricks import enabled as databricks_enabled, DatabricksStore, AISearchStore
from integrations.entire import semantic_diff

logger = logging.getLogger("stellar")


class AnalysisError(Exception):
    pass


def _trace_analysis(context):
    if os.getenv("MLFLOW_ENABLED", "false").lower() not in {"1", "true", "yes", "on"}:
        return llm_analyze(context)
    try:
        import mlflow
        if hasattr(mlflow, "trace"):
            @mlflow.trace(name="stellar.analysis", span_type="AGENT")
            def traced():
                return llm_analyze(context)
            return traced()
    except Exception as exc:
        logger.warning("MLflow tracing unavailable: %s", exc)
    return llm_analyze(context)


def _coverage(tests, affected, changed):
    covered = set()
    corpus = [(t["file"], t.get("text", "").lower()) for t in tests]
    for item in list(affected) + list(changed):
        leaf = str(item).split(".")[-1].lower()
        for _, text in corpus:
            if leaf and leaf in text:
                covered.add(item)
                break
    return covered


def _missed(affected, covered, history):
    out = []
    history_text = " ".join(str(x) for x in history).lower()
    for eid, item in affected.items():
        if eid in covered:
            continue
        terms = [t.lower() for t in str(eid).replace(".", "/").split("/") if len(t) > 2]
        evidence = sum(1 for t in terms if t in history_text)
        score = min(100, 45 + int(item.get("depth", 0)) * 12 + evidence * 15)
        out.append({
            "entity_id": eid,
            "missed_risk_score": score,
            "reason": "affected path lacks direct test evidence" + (" and has historical incident references" if evidence else ""),
            "supporting_checkpoint_id": history[0].get("commit_id") if evidence and history else None
        })
    return sorted(out, key=lambda x: -x["missed_risk_score"])[:8]


def _search_history(query, repo_name, local_history):
    if not databricks_enabled():
        return local_history
    try:
        return AISearchStore().search(query, k=8, repo=repo_name)
    except Exception as exc:
        logger.warning("Databricks AI Search unavailable; falling back to local checkpoints: %s", exc)
        return local_history


def run_analysis(repo_path, repo_name, commit, db_path=None, semantic_base=None):
    allow_fallback = os.getenv("STELLAR_ALLOW_LOCAL_FALLBACK", os.getenv("IMPACTLENS_ALLOW_LOCAL_FALLBACK", "true")).lower() in {"1", "true", "yes", "on"}
    if not databricks_enabled() and not allow_fallback:
        raise AnalysisError("Databricks is disabled. Set DATABRICKS_ENABLED=true or STELLAR_ALLOW_LOCAL_FALLBACK=true.")

    try:
        result = build(repo_path, commit, repo_name)
    except PipelineError as exc:
        raise AnalysisError(str(exc)) from exc

    tests = inventory(repo_path)
    affected = [{"entity_id": k, **v} for k, v in sorted(result["all_affected"].items(), key=lambda x: (x[1].get("depth", 0), x[0]))]
    covered = _coverage(tests, result["all_affected"], result["changed_entities"])
    recommendations = rank(tests, [a for a in affected], result["changed_entities"])

    history_query = " ".join([result["checkpoint"].get("prompt", "") or "", result["checkpoint"].get("checkpoint_summary", "") or "", *result["changed_entities"]])
    historical = _search_history(history_query, repo_name, result["historical_checkpoints"])
    missed = _missed(result["all_affected"], covered, historical)

    risk = score_change(result["changed_entities"], result["all_affected"], covered, historical, result["checkpoint"], result.get("graph_evidence"))

    context = {
        "repo": repo_name,
        "commit": result["commit_meta"],
        "changed_files": result["changed_files"],
        "changed_entities": result["changed_entities"],
        "affected_entities": affected,
        "developer_checkpoint": result["checkpoint"],
        "historical_checkpoints_matched": historical,
        "risk": risk,
        "recommended_tests": recommendations,
        "candidate_missed_risks": missed,
        "evidence": {"graph": result["graph_evidence"]}
    }

    report = _trace_analysis(context)
    run_id = str(uuid.uuid4())
    final = {
        **context,
        "report": report,
        "data_plane": "databricks" if databricks_enabled() else "local-demo",
        "run_id": run_id
    }

    if semantic_base:
        try:
            final["semantic_diff"] = semantic_diff(repo_path, semantic_base, commit)
        except Exception as exc:
            final["semantic_diff"] = {"error": str(exc), "base": semantic_base, "head": commit}

    if databricks_enabled():
        try:
            DatabricksStore().write(result, risk, tests=tests, recommended_tests=recommendations, missed=missed, run_id=run_id, llm_engine=report.get("engine", "unknown"))
            final["databricks_write"] = "ok"
        except Exception as exc:
            final["databricks_write"] = f"error: {exc}"

    return final
"""Deterministic, repository-agnostic impact scoring for Stellar."""
from __future__ import annotations


def _band(score: float) -> str:
    if score <= 30:
        return "LOW"
    if score <= 60:
        return "MEDIUM"
    if score <= 80:
        return "HIGH"
    return "CRITICAL"


def jsonish(value):
    try:
        import json
        return json.dumps(value, default=str)
    except Exception:
        return str(value)


def score_change(changed_entities, all_affected, covered_entities, historical_matches, checkpoint, graph=None):
    n = len(all_affected)
    direct = sum(1 for v in all_affected.values() if v.get("depth") == 1)
    max_depth = max([int(v.get("depth", 0)) for v in all_affected.values()] or [0])
    # Criticality is inferred only from graph evidence. Route/public/entrypoint
    # entities are more exposed; otherwise fan-in is used as the proxy.
    kinds = []
    if graph:
        for item in graph:
            text = jsonish(item).lower()
            if any(k in text for k in ("route", "endpoint", "handler", "entrypoint")):
                kinds.append(1)
    exposure = min(100, (direct / max(1, n)) * 100 if n else 0)
    public_surface = 100 if kinds else min(100, direct * 12)
    gap = (sum(e not in covered_entities for e in all_affected) / n * 100) if n else 0
    history = min(len(historical_matches) / 5, 1) * 100
    intent = 0 if (checkpoint.get("prompt") or checkpoint.get("agent_reasoning")) else 100
    depth = min(max_depth / 5, 1) * 100
    breadth = min(n / 15, 1) * 100
    score = round(min(100, .20 * exposure + .15 * breadth + .15 * public_surface + .18 * gap + .10 * history + .10 * intent + .12 * depth), 1)
    reasons = []
    if direct:
        reasons.append(f"{direct} direct graph relationship(s) were identified")
    if n:
        reasons.append(f"{n} affected graph entities were identified")
    if max_depth > 1:
        reasons.append(f"impact reaches {max_depth} dependency levels")
    if public_surface >= 70:
        reasons.append("graph evidence indicates an externally exposed or entry-point surface")
    if gap:
        reasons.append(f"{round(gap)}% of affected entities lack matched test evidence")
    if historical_matches:
        reasons.append(f"{len(historical_matches)} historical checkpoint record(s) were retrieved")
    if intent:
        reasons.append("checkpoint intent is unavailable or incomplete")
    return {
        "risk_score": score,
        "risk_band": _band(score),
        "components": {
            "graph_exposure": round(exposure, 1),
            "blast_radius": round(breadth, 1),
            "surface_criticality": round(public_surface, 1),
            "coverage_gap": round(gap, 1),
            "historical_evidence": round(history, 1),
            "checkpoint_uncertainty": round(intent, 1),
            "dependency_depth": round(depth, 1),
        },
        "risk_reasons": reasons,
    }
